PRERELEASE = re.compile(r"^[-.]?(a|b|rc|alpha|beta|dev|pre|canary|next)", re.I)


def version_key(version: str) -> tuple[int, int, int, int, str]:
    """Orders versions like 1.2.3 < 1.10.0; pre-releases (1.0.0-rc.1, 1.0.0b1) before the release. Mirrors index.ts."""
    m = re.match(r"^v?(\d+)(?:\.(\d+))?(?:\.(\d+))?(.*)$", version.strip())
    if not m:
        return (-1, 0, 0, 0, version)
    rest = m.group(4) or ""
    return (int(m.group(1)), int(m.group(2) or 0), int(m.group(3) or 0), 0 if PRERELEASE.match(rest) else 1, rest)


def unknown_library(name: str) -> types.CallToolResult:
    return text(f"Unknown library \"{name}\". Libraries: {', '.join(lib['name'] for lib in LIBRARIES)}.", True)
TOKEN = re.compile(r"\w+", re.UNICODE)


class SearchIndex:
    """Dependency-free BM25 over title, section and body with prefix matching (mirrors the TS server's MiniSearch)."""

    FIELDS = (("title", 4.0), ("section", 2.0), ("markdown", 1.0))
    K1, B = 1.2, 0.75

    def __init__(self, pages: list[dict[str, Any]]) -> None:
        self.pages = pages
        self.tf: list[dict[str, Counter[str]]] = []
        self.lengths: dict[str, list[int]] = {field: [] for field, _ in self.FIELDS}
        self.postings: dict[str, set[int]] = {}
        for i, page in enumerate(pages):
            counts = {field: Counter(TOKEN.findall(str(page.get(field) or "").lower())) for field, _ in self.FIELDS}
            self.tf.append(counts)
            for field, _ in self.FIELDS:
                self.lengths[field].append(sum(counts[field].values()))
                for term in counts[field]:
                    self.postings.setdefault(term, set()).add(i)
        self.average = {f: (sum(v) / len(v) if v else 0.0) or 1.0 for f, v in self.lengths.items()}
        self.vocabulary = sorted(self.postings)

    def _expand(self, term: str) -> list[tuple[str, float]]:
        expanded = [(term, 1.0)] if term in self.postings else []
        if len(term) >= 3:
            start = bisect.bisect_left(self.vocabulary, term)
            for candidate in self.vocabulary[start : start + 50]:
                if not candidate.startswith(term):
                    break
                if candidate != term:
                    expanded.append((candidate, 0.5))
        return expanded

    def search(self, query: str, limit: int, only: set[int] | None = None) -> list[dict[str, Any]]:
        scores: dict[int, float] = {}
        total = len(self.pages)
        for term in TOKEN.findall(query.lower()):
            for candidate, weight in self._expand(term):
                docs = self.postings[candidate]
                idf = math.log(1 + (total - len(docs) + 0.5) / (len(docs) + 0.5))
                for i in docs:
                    if only is not None and i not in only:
                        continue
                    score = 0.0
                    for field, boost in self.FIELDS:
                        tf = self.tf[i][field][candidate]
                        if tf:
                            norm = 1 - self.B + self.B * self.lengths[field][i] / self.average[field]
                            score += boost * tf * (self.K1 + 1) / (tf + self.K1 * norm)
                    scores[i] = scores.get(i, 0.0) + weight * idf * score
        ranked = sorted(scores.items(), key=lambda item: item[1], reverse=True)
        return [self.pages[i] for i, _ in ranked[:limit]]


INDEX = SearchIndex(PAGES)
COMPONENT_IDS = {i for i, p in enumerate(PAGES) if p["kind"] == "component"}


def search_pages(query: str, limit: int, only_components: bool = False, library: str | None = None) -> list[dict[str, Any]]:
    only = set(COMPONENT_IDS) if only_components else None
    if library:
        in_library = {i for i, p in enumerate(PAGES) if p.get("library") == library}
        only = in_library if only is None else only & in_library
    return INDEX.search(query, limit, only)


def find_page(path: str) -> dict[str, Any] | None:
    wanted = re.sub(r"^docs://[^/]+/", "", path).lstrip("/")
    return next((p for p in PAGES if p["path"] == wanted), None)


def snippet(markdown: str, query: str) -> str:
    body = re.sub(r"^#+\s.*$", "", markdown, count=1, flags=re.M).strip()
    first = (TOKEN.findall(query.lower()) or [""])[0]
    start = max(0, body.lower().find(first) - 80)
    return ("…" if start else "") + re.sub(r"\s+", " ", body[start : start + 320]) + "…"


